#include <stdio.h>

#define MAXF 8
#define MAXR 32

int faults_fifo(const int *r, int n, int m) {
    int q[MAXF], head = 0, f = 0, c = 0;
    for (int i = 0; i < n; i++) {
        int hit = 0;
        for (int j = 0; j < f; j++) if (q[j] == r[i]) { hit = 1; break; }
        if (hit) continue;
        c++;
        if (f < m) q[f++] = r[i];
        else { q[head] = r[i]; head = (head + 1) % m; }
    }
    return c;
}

int faults_lru(const int *r, int n, int m) {
    int q[MAXF], last[MAXF], f = 0, c = 0;
    for (int i = 0; i < n; i++) {
        int hit = -1;
        for (int j = 0; j < f; j++) if (q[j] == r[i]) { hit = j; break; }
        if (hit >= 0) { last[hit] = i; continue; }
        c++;
        if (f < m) { q[f] = r[i]; last[f] = i; f++; }
        else {
            int v = 0;
            for (int j = 1; j < m; j++) if (last[j] < last[v]) v = j;
            q[v] = r[i]; last[v] = i;
        }
    }
    return c;
}

int faults_opt(const int *r, int n, int m) {
    int q[MAXF], f = 0, c = 0;
    for (int i = 0; i < n; i++) {
        int hit = 0;
        for (int j = 0; j < f; j++) if (q[j] == r[i]) { hit = 1; break; }
        if (hit) continue;
        c++;
        if (f < m) { q[f++] = r[i]; continue; }
        int v = -1, far = -1;
        for (int j = 0; j < m; j++) {
            int k = i + 1;
            while (k < n && r[k] != q[j]) k++;
            if (k > far) { far = k; v = j; }
        }
        q[v] = r[i];
    }
    return c;
}

/* 简单 Clock：只用访问位 */
int faults_clock(const int *r, int n, int m) {
    int q[MAXF], ref_bit[MAXF], f = 0, ptr = 0, c = 0;
    for (int i = 0; i < n; i++) {
        int hit = 0;
        for (int j = 0; j < f; j++) if (q[j] == r[i]) { ref_bit[j] = 1; hit = 1; break; }
        if (hit) continue;
        c++;
        if (f < m) { q[f] = r[i]; ref_bit[f] = 1; f++; continue; }
        while (ref_bit[ptr] == 1) { ref_bit[ptr] = 0; ptr = (ptr + 1) % m; }
        q[ptr] = r[i]; ref_bit[ptr] = 1; ptr = (ptr + 1) % m;
    }
    return c;
}

int main(void) {
    int ref[] = {7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1};
    int n = 20;
    printf("reference string = 7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1\n");
    printf("frames |  OPT | FIFO |  LRU | Clock\n");
    printf("-------+------+------+------+------\n");
    for (int m = 3; m <= 5; m++)
        printf("  %d    | %4d | %4d | %4d | %4d\n", m,
               faults_opt(ref, n, m), faults_fifo(ref, n, m),
               faults_lru(ref, n, m), faults_clock(ref, n, m));
    printf("textbook values for 3 frames: OPT=9, FIFO=15, LRU=12\n");
    return 0;
}
